      "用法：把层级密钥放进快捷栏，对着任意一扇门按 G 就能切到它绑定的层级；到了那边，对着门再按一次 G 就回到原处。门不必是专属的，层级里原本的门、闸、出口都可以。",
      "枢纽改动：玩家到了一个层级之后，枢纽里那个层级还是不能进入，必须要在那个层级里找到对应的层级钥匙，并在枢纽的门打开。在枢纽里用层级密钥开门，并不会使层级密钥消失。枢纽里只有 Level 1 和 Level 11 不使用层级密钥就能打开。",
