      "除了外部景象的破败，一切事物的物理性质也都无比异常；此处的所有结构都不由实在的物质构成，即使是转瞬即逝的杂乱之物也无法在此积存。所有的物体都不断向着破碎之地的远方漫游，并在抵达地平线时消解掉自己原先的样态，陷入那不断变化、衰退的熵增地域里，落进那无比恐怖、混乱的破碎环境中。",
