      "除「克拉肯」之外，海洋中没有其他实体被完全的记录过，但估计有 200 种实体栖息在 Level 29 的海洋中。由于缺乏设备和担心人员流失，目前还未对海洋进行更深层次的勘探 —— 所有研究结果都表明，目前人们只揭露了这个被认为前所未闻的生态系统的冰山一角。",
