      "入口：在 Level 29 航行 1500 格后进入这里。若此时有两个或两个以上的人试图同等的速度同时进入本层级，从而会引发什么现象仍然未知。",
      "出口：找到一个用草搭制的床上睡上一觉，就会在 Level 11 醒来。",
