      "【最喜欢的面点】被流浪者认为是最喜欢的面点被确定是最致命的。当与该种面点的距离少于 1 英尺时，一种不可抗拒的想要吃掉这份美味的冲动会占据这位流浪者的脑海。若一旦被食用：起初三分钟喉咙发炎红肿，十分钟胃炎，二十分钟红皮病，之后呼吸困难，最终心脏衰竭。",
