      "打爆小行星（不常见）：进入一个含有多块屏幕的房间，屏幕上显示的是外太空的景象。屏幕上会出现小行星，需要用泡沫球击中出现小行星的屏幕 —— 若至少击中 10 颗即为胜利。获胜后生成几个装有各种可饮用液体的太空主题瓶子；失败后会被传送至 Level 6，或房间里生成一条牧蛇。",
      "躲避激光（不常见）：一边躲避激光，一边尝试按下房间各处的发光按钮。另一个版本是坚持躲避移动的激光 3 分钟。获胜后房间里生成一个记忆罐，旁边还有多包食物和多瓶杏仁水；失败后会被传送至别处。",
      "鼹鼠洞（极不常见）：面对一系列走廊，其中的洞会发出不同颜色的光。需要把一个塑料球放进指定颜色的洞里 —— 球会滚至另一条走廊中的同类洞，4 分钟内完成 20 次方可胜出。获胜后：未知。失败后：房间中生成 4 条猎犬。",
      "据信霓虹区还存在其他游戏，但尚未得到记录。",
