      "入口和出口：已知的唯一方法是进入 Level 11 的购物中心或商场，或在 Level 22 上楼。如果你从 Level 11 进入，请从入口处返回。如果你来自 Level 22，请从你身后的楼梯返回。您也可以通过办公室入口以进入 Level 45。",
