    body: [
      "痛楚是一个不可理解的异常现象，处于后室之中。虽然有传言说它存在，但它不能按常规方式进入 —— 假若真的有进入的方式的话。",
      "后室是一座监狱，但在这个现实之平台的后方潜藏着的事物，是未知的、无限的、不可预测的。即使有生灵逃离了后室，彼岸的路途也隐藏着大量的未能探明之物与无可辨识之物。人类害怕未知，因此徒劳地创造理论来试图解释未知。他们大错特错。也许无知真的是幸福……因为一旦真相被知晓，它就不会被遗忘。真相会捕猎他们。",
      "根据五位目击者的说法，这是一个新的世界 —— 于 Level 0 中呈现，并在呈现的数小时后毫无预兆地消失。目击者声称这是一个黑白色的区域，靠近这个区域会导致强烈的恐惧感。",
      "这一异常区域内部包含多个坟墓，排列成完美的圆圈，围绕着中心一个不知名的、戴帽男子的破损石像。七英尺高的枯树在散乱的坟墓旁构成同样的圆圈排列。踩在散落在地上的被分解了的树叶时，它们传出刺耳的尖叫声。黑暗吞噬了这个区域，而唯一的光源是孤寂而静止的月亮。浓重的灰雾环绕整个区域，让能见度降低到了仅有五英尺。",
      "每个墓碑都有着一位死者的姓名，还有一条短句以形容他们的死因。墓碑上书写着两个日期，似乎是他们的生日与忌日。尽管 M.E.G. 尽最大努力去试图寻找这些姓名的拥有者，但未曾发现与之相关联的任何流浪者。",
      "在第一次也是唯一一次对痛楚进行的进入尝试时，雾的灰色开始渗入 Level 0 的黄色墙纸，随着异常的扩散，墙纸的颜色逐渐失去了饱和度。任何碰触到异常表面的物品、实体与人类会迅速转变为灰色，并最终化为灰烬。",
      "此前人们认为遭受这种命运的流浪者已经死亡，但这只是在部分上正确 —— 尽管这些流浪者的肉体已经不复存在，但他们的灵魂仍然自由游荡。这些迷失的灵魂无处可去，他们注定要在痛楚与其中无数的坟墓中漫步，被迫重温他们最糟糕的记忆。目击者听到了这些灵魂的尖叫、哭泣和低声低语，以及对结束对他们的折磨的祈求。然而这些信息似乎在循环 —— 每次接收到的信息都是以相同的语气重复传递相同的消息。",
      "入口：在 Level 0 有时会出现一团灰雾挡住去路，如果你进入这团雾，你的灵魂便会来到这里。出口：你的生命值、理智值不复存在，也不会减少。你将会永远留在这里。",
    ],
