// ======== 防御：数组里出现空位（比如多打了一个逗号）会让整个档案界面崩溃 ========
// 之前就发生过一次：ARCHIVES 中间有个空槽，renderManual 读 a.level 直接抛错，
// 结果「层级档案」界面永远打不开。这里在加载时把空位剔掉，以后再加档案也不会重演。
(function () {
  let bad = 0;
  for (let i = ARCHIVES.length - 1; i >= 0; i--) {
    if (!ARCHIVES[i] || typeof ARCHIVES[i] !== "object") { ARCHIVES.splice(i, 1); bad++; }
  }
  if (bad) {
    try { console.warn("[archive] 剔除了 " + bad + " 个空档案条目（数组里有空位）"); } catch (e) { /* 忽略 */ }
  }
})();

// ======== 结局档案（含彩蛋）========
